import{_ as t,c as e,o as l,ag as s}from"./chunks/framework.DfL_BkQ-.js";const g=JSON.parse('{"title":"Приват территории","description":"","frontmatter":{},"headers":[],"relativePath":"features/privates.md","filePath":"features/privates.md"}'),a={name:"features/privates.md"};function c(p,o,r,n,i,d){return l(),e("div",null,[...o[0]||(o[0]=[s('<h1 id="приват-территории" tabindex="-1">Приват территории <a class="header-anchor" href="#приват-территории" aria-label="Permalink to &quot;Приват территории&quot;">​</a></h1><h2 id="▌-основная-информация" tabindex="-1"><span style="color:#3b82f6;">▌ Основная информация</span> <a class="header-anchor" href="#▌-основная-информация" aria-label="Permalink to &quot;&lt;span style=&quot;color: #3b82f6&quot;&gt;▌ Основная информация&lt;/span&gt;&quot;">​</a></h2><p>Мы решили попробовать что-то новое и полностью убрали функцию деревянного топорика для привата. Теперь всё намного проще!</p><p><strong>Прописываем команду ➝ выбираем необходимый размер ➝ устанавливаем защитный блок</strong></p><p>Всего <strong>3</strong> шага и приват создан. Захотел удалить? Сломал блок и готово.</p><div class="warning custom-block"><p class="custom-block-title">Важно</p><p>При создании привата или присвоения территории следует соблюдать <a href="/rules/#_5-система-приватов">правила</a>.</p></div><div class="tip custom-block"><p class="custom-block-title">Информация</p><p>Все команды, которые помогут с гибкой настройкой приватов, можно найти в <code>/ps help</code>.</p></div><ol><li>Пишем в чат <code>/ps get</code></li><li>Выбираем <strong>мышкой</strong> размер территории из списка в чате</li><li>Устанавливаем <strong>защитный блок</strong>, появившийся в инвентаре</li></ol><blockquote><p>Проверить, создался ли регион, можно командой: <code>/ps info</code></p></blockquote><details class="details custom-block"><summary>📊 Лимиты приватов для привилегий (Нажмите, чтобы открыть)</summary><ul><li><strong>ᴘʟᴀʏᴇʀ</strong> (Обычный игрок) — 1 приват и 2 точки дома</li><li><span style="color:#3b82f6;"><strong>ᴜɴɪǫᴜᴇ</strong></span> — 2 привата и 3 точки дома</li><li><span style="color:#a855f7;"><strong>ʜᴇʀᴏɪᴄ</strong></span> — 3 привата и 4 точки дома</li><li><span style="color:#eab308;"><strong>ᴍʏᴛʜɪᴄ</strong></span> — 4 привата и 5 точек дома</li><li><span style="color:#ef4444;"><strong>ᴄᴏsᴍɪᴄ</strong></span> — 5 приватов и 6 точек дома</li></ul></details><h2 id="▌-добавление-и-удаление-в-регион" tabindex="-1"><span style="color:#3b82f6;">▌ Добавление и удаление в регион</span> <a class="header-anchor" href="#▌-добавление-и-удаление-в-регион" aria-label="Permalink to &quot;&lt;span style=&quot;color: #3b82f6&quot;&gt;▌ Добавление и удаление в регион&lt;/span&gt;&quot;">​</a></h2><p>Чтобы дать возможность твоему другу разрушать и устанавливать блоки в привате, необходимо его добавить в регион. Это делается почти так же, как и раньше.</p><p><strong>Добавить участника (Жильца):</strong></p><blockquote><p>▪ Пишем в чат <code>/ps add &lt;ник&gt;</code></p></blockquote><p><strong>Добавить владельца (Основателя):</strong></p><blockquote><p>▪ Пишем в чат <code>/ps addowner &lt;ник&gt;</code></p></blockquote><p><strong>Удалить из региона:</strong></p><blockquote><p>▪ Пишем в чат <code>/ps remove &lt;ник&gt;</code> (жильца) ▪ Пишем в чат <code>/ps removeowner &lt;ник&gt;</code> (владельца)</p></blockquote><h2 id="▌-аренда-и-продажа-региона" tabindex="-1"><span style="color:#3b82f6;">▌ Аренда и продажа региона</span> <a class="header-anchor" href="#▌-аренда-и-продажа-региона" aria-label="Permalink to &quot;&lt;span style=&quot;color: #3b82f6&quot;&gt;▌ Аренда и продажа региона&lt;/span&gt;&quot;">​</a></h2><p>Ты можешь сдавать в аренду свой регион или же арендовать чужой. Смотри, здесь всё просто.</p><p><strong>Сдать свой регион в аренду:</strong></p><blockquote><p>▪ Пишем в чат <code>/ps rent lease &lt;цена&gt; &lt;период&gt;</code></p></blockquote><div class="tip custom-block"><p class="custom-block-title">Правильный вариант</p><p>/ps rent lease 1000 1d (1000 монет за 1 день)</p></div><div class="danger custom-block"><p class="custom-block-title">Неправильный вариант</p><p>/ps rent lease 1,000 1д (нельзя использовать запятые и русские буквы)</p></div><blockquote><p><strong>Обозначения времени:</strong></p><ul><li><code>h</code> — час</li><li><code>d</code> — день</li><li><code>w</code> — неделя</li></ul></blockquote><p><strong>Арендовать чужой регион:</strong></p><blockquote><p>▪ Пишем в чат <code>/ps rent rent</code> (находясь внутри региона)</p></blockquote><p><strong>Продажа и покупка региона:</strong></p><blockquote><p>▪ <code>/ps sell &lt;цена&gt;</code> — Выставить регион на продажу (стоя внутри) ▪ <code>/ps buy</code> — Купить регион (стоя внутри)</p></blockquote><h2 id="▌-остальные-команды" tabindex="-1"><span style="color:#3b82f6;">▌ Остальные команды</span> <a class="header-anchor" href="#▌-остальные-команды" aria-label="Permalink to &quot;&lt;span style=&quot;color: #3b82f6&quot;&gt;▌ Остальные команды&lt;/span&gt;&quot;">​</a></h2><ul><li><code>/ps name &lt;название&gt;</code> — изменить название региона</li><li><code>/ps list</code> — список личных регионов</li><li><code>/ps view</code> — включить отображение границ региона (визуал)</li><li><code>/ps flag</code> — изменить флаги региона (PVP и т.д.)</li><li><code>/ps hide</code> — скрыть защитный блок (визуально)</li><li><code>/ps unhide</code> — раскрыть защитный блок</li><li><code>/ps unclaim</code> — удалить регион (стоя внутри)</li></ul>',31)])])}const b=t(a,[["render",c]]);export{g as __pageData,b as default};
